//! The Wake Profile schema set, embedded from the current spec folder.
//!
//! Spec: W§2 — profile message payloads, the registration credential's payload and the opened hint have JSON Schemas
//! (draft 2020-12) generated by `v1.0/dsip-wake-schemas-draft/generate_schemas.py`; `build.rs` fails the build if the
//! committed files drift from the generator. Impl: format assertions are off, matching the Python harness and
//! `dsip-schema`.

use std::collections::HashMap;
use std::sync::OnceLock;

use jsonschema::Validator;
use serde_json::Value;

macro_rules! schema {
    ($name:literal) => {
        (
            $name,
            include_str!(concat!(
                env!("DSIP_SPEC"),
                "/v1.0/dsip-wake-schemas-draft/schemas/",
                $name,
                ".schema.json"
            )),
        )
    };
}

/// `(name, json text)` for every schema in the profile set.
/// `(name, json text)` for every schema in the profile set.
pub const SCHEMAS: &[(&str, &str)] = &[
    schema!("wake-enrol"),
    schema!("wake-accepted"),
    schema!("wake-register"),
    schema!("wake"),
    schema!("wake-registration"),
    schema!("wake-hint"),
];

fn compiled() -> &'static HashMap<&'static str, Validator> {
    static CELL: OnceLock<HashMap<&'static str, Validator>> = OnceLock::new();
    CELL.get_or_init(|| {
        // A schema that does not parse or compile is left out, so `schema_ok` refuses its instances rather than
        // the process panicking; `every_schema_compiles` fails the build on such a schema.
        SCHEMAS
            .iter()
            .filter_map(|(name, text)| {
                let schema: Value = serde_json::from_str(text).ok()?;
                let v = jsonschema::options()
                    .should_validate_formats(false)
                    .build(&schema)
                    .ok()?;
                Some((*name, v))
            })
            .collect()
    })
}

/// Whether `instance` is valid against the named profile schema. An unknown name is invalid.
pub fn schema_ok(name: &str, instance: &Value) -> bool {
    compiled().get(name).is_some_and(|v| v.is_valid(instance))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_schema_compiles() {
        for (name, _) in SCHEMAS.iter() {
            assert!(
                compiled().contains_key(name),
                "wake schema {name} does not compile"
            );
        }
    }
}
